local function ParseRangeProbes(payload)
    local data = {}
    for entry in payload:gmatch("[^;]+") do
        local range, ids = entry:match("^(%d+):(.+)$")
        if range then
            local list = {}
            for id in ids:gmatch("%d+") do
                list[#list + 1] = tonumber(id)
            end
            data[tonumber(range)] = list
        end
    end
    return data
end

function ns.GetLibRangeCheckQFXItemData()
    local data = ns.LibRangeCheckQFXItemData
    if data then
        return data
    end
    data = {
        friend = ParseRangeProbes(FRIEND_PAYLOAD),
        harm = ParseRangeProbes(HARM_PAYLOAD),
    }
    ns.LibRangeCheckQFXItemData = data
    return data
end

